    "description": "年轻女性，留着带蜜糖色挑染的长波浪暗金发，自然散落在肩膀上。皮肤白皙，鼻梁和脸颊上有可见的自然雀斑。穿着一套配套的[灰色]两件式运动休闲套装，包含一件罗纹无袖短款背心和一条臀部带有工装贴袋的紧身短裤。脚穿侧面带有白色Nike标志的黑色短袜。",
    "anatomy_and_proportions": "身材紧致匀称，突出运动感的下半身曲线。跪姿与紧身短裤衬托出饱满的臀部线条，纤细的腰身自然过渡到臀胯曲线。肩部放松。",
    "clothing_details": "[灰色]背心具有罗纹质感和工字背剪裁。短裤为高腰紧身弹力面料，每侧裤腿后方均有翻盖口袋。黑色标准运动短袜。"
  },
  "pose": {
    "stance": "跪在铺有地毯的地板上，身体与镜面呈约45度角侧后身朝向，躯干微微向镜子方向扭转。",
    "limbs": "双腿向后折叠，小腿贴紧地毯，重心向脚跟靠拢。左手自然垂于身侧，右手屈肘举起智能手机拍摄镜中倒影。",
    "head_and_gaze": "头部转向镜子，眼睛看着手机屏幕中的倒影，下巴微收。"
  },
  "environment": {
    "setting": "室内[卧室]环境。",
    "background_elements": "人物正后方是一扇带银色把手的白色面板门。右侧靠墙地板上放着一台[黑色Marshall吉他音箱]。地面铺满柔软的灰色全铺地毯，墙角带有白色踢脚线。",
    "foreground_elements": "画面边缘带有黑色细框全身镜的侧边轮廓。"
  },
  "camera": {
    "perspective": "全身立镜拍摄的镜面自拍视角。",
    "shot_type": "中全景构图，捕捉从膝盖到头顶的范围。",
    "focal_length": "相当于智能手机主摄的24mm至28mm。",
    "depth_of_field": "适度到较深景深，保持人物和紧邻背景清晰。"
  },
  "lighting": {
    "type": "自然柔和漫射日光。",
    "source": "来自右侧画外窗户的自然光源，柔和照亮面部与侧面轮廓。",
    "quality": "光线柔和均匀，在左侧身体和地毯接触处留下自然的轻微阴影。"
  }
}

